import sys, random
sys.path.insert(0, ".")
from lib import f
def orig(a):
    r = []
    for x in a:
        if x % 2 == 0: r.append(x * x)
    return r
rnd = random.Random(11)
cases = [[], [1, 2, 3, 4], [0], [-2, -3, 5, 6], (2, 4, 6), [1, 3, 5], [2.0, 1.5, 4.0], [10**10]]
cases += [[rnd.randint(-100, 100) for _ in range(rnd.randint(0, 30))] for _ in range(200)]
for c in cases:
    r = f(c)
    e = orig(c)
    if r != e or type(r) is not list or [type(x) for x in r] != [type(x) for x in e]:
        sys.exit(1)
if f(x for x in [1, 2, 3, 4]) != [4, 16]:
    sys.exit(1)
sys.exit(0)
